namespace Fps.Desktop.Rendering;

internal static class SkyShader
{
	public const string Fragment = "#version 330\nout vec4 finalColor;\nuniform sampler2D cloudMap;\nuniform vec3 cameraForward;\nuniform vec3 cameraRight;\nuniform vec3 cameraUp;\nuniform vec4 pixelToRay;\nuniform vec3 sunDirection;\nuniform vec3 moonDirection;\nuniform vec3 skyZenith;\nuniform vec3 skyHorizon;\nuniform vec3 belowHorizon;\nuniform vec3 conditions;\nuniform vec4 sizesAndMotion;\n\nconst float PI = 3.14159265;\n\nfloat starHash(ivec2 cell) {\n    uvec2 n = uvec2(cell);\n    uint h = (n.x * 0x8da6b343u) ^ (n.y * 0xd8163841u);\n    h ^= h >> 16;\n    h *= 0x7feb352du;\n    h ^= h >> 15;\n    return float(h & 65535u) / 65535.0;\n}\n\nfloat stars(vec2 uv, float time) {\n    float rotation = time * sizesAndMotion.w;\n    float c = cos(rotation);\n    float s = sin(rotation);\n    vec2 grid = (mat2(c, s, -s, c) * uv) * 66.0;\n    ivec2 cell = ivec2(floor(grid));\n    float seed = starHash(cell);\n    vec2 offset = vec2(starHash(cell + ivec2(74, 19)), starHash(cell + ivec2(126, 11)));\n    float distanceToStar = length(fract(grid) - mix(vec2(0.24), vec2(0.76), offset));\n    float size = mix(0.085, 0.22, seed);\n    float glow = 1.0 - smoothstep(size * 0.22, size, distanceToStar);\n    float twinkle = 0.78 + 0.22 * sin(seed * 93.0 + time * 1.1);\n    return step(0.965, seed) * glow * twinkle;\n}\n\nvoid main() {\n    vec2 screen = (gl_FragCoord.xy * pixelToRay.xy * 2.0 - 1.0) * pixelToRay.zw;\n    vec3 ray = normalize(cameraForward + cameraRight * screen.x + cameraUp * screen.y);\n    float sunset = conditions.x;\n    float night = conditions.y;\n    float time = conditions.z;\n    float height = abs(sin(ray.y * PI * 0.5));\n    vec3 color = mix(skyHorizon, skyZenith, height);\n    float sunDistance = length(ray - sunDirection);\n    float west = pow(max(0.0, 1.0 - sunDistance * sunDistance), 2.0);\n    color = mix(color, vec3(1.0, 0.52, 0.40), west * sunset * (1.0 - night) * (1.0 - height) * 0.42);\n    float horizonMask = 1.0 - smoothstep(0.0, 0.11, -ray.y);\n    color = mix(belowHorizon, color, horizonMask);\n\n    vec2 skyUv = ray.xz / sqrt(max(ray.y, 0.02));\n    float moonRadius = sizesAndMotion.y * (1.0 + cos(moonDirection.y * PI) * 0.25);\n    float moonDistance = length(ray - moonDirection);\n    float moonDisk = (1.0 - smoothstep(moonRadius * 0.93, moonRadius, moonDistance)) * horizonMask;\n    if (night > 0.01 && ray.y > 0.0)\n        color += vec3(0.86, 0.90, 1.0) * stars(skyUv, time) * night *\n            smoothstep(0.025, 0.16, ray.y) * (1.0 - moonDisk) * 0.72;\n\n    float sunRadius = sizesAndMotion.x * (1.0 + cos(sunDirection.y * PI) * 0.25);\n    float sunDisk = 1.0 - smoothstep(sunRadius * 0.87, sunRadius, sunDistance);\n    float halo = exp(-sunDistance * sunDistance / (sunRadius * sunRadius * 2.9));\n    vec3 sunTint = mix(vec3(1.0, 0.94, 0.62), vec3(1.0, 0.39, 0.16), sunset);\n    float sunVisibility = smoothstep(-0.11, 0.015, sunDirection.y) * horizonMask * (1.0 - moonDisk);\n    color += sunTint * halo * 0.32 * sunVisibility;\n    color = mix(color, mix(sunTint, vec3(1.0), 0.52), sunDisk * sunVisibility);\n\n    if (moonDisk > 0.0) {\n        // A interseção do raio com a esfera dá a normal para a fase lunar.\n        float projection = dot(ray, moonDirection);\n        float chord = sqrt(max(0.0, projection * projection - 1.0 + moonRadius * moonRadius));\n        vec3 normal = normalize(ray * (projection - chord) - moonDirection);\n        float phase = pow(clamp(dot(normal, sunDirection), 0.04, 1.0), 1.45);\n        vec3 unlit = mix(color * 0.88, vec3(0.075, 0.084, 0.15), night * 0.62);\n        color = mix(color, mix(unlit, vec3(1.0, 0.95, 0.76), phase), moonDisk);\n    }\n\n    if (ray.y > 0.0) {\n        vec2 wind = vec2(0.95, 0.31) * time * sizesAndMotion.z;\n        vec2 plane = skyUv * 0.16;\n        float low = smoothstep(0.44, 0.65,\n            texture(cloudMap, plane * 1.2 - wind * 0.079).b);\n        float middle = smoothstep(0.47, 0.68,\n            texture(cloudMap, plane * 0.91 - wind * 0.089).g + low * 0.045);\n        float high = smoothstep(0.49, 0.71,\n            texture(cloudMap, plane * 0.78 - wind * 0.10).r + middle * 0.05);\n        float cloudMask = max(high, max(middle * 0.81, low * 0.66));\n        cloudMask *= smoothstep(0.045, 0.24, ray.y);\n        vec3 cloud = mix(vec3(0.81, 0.84, 0.97), vec3(1.0), max(high, middle * 0.43));\n        cloud = mix(cloud, vec3(1.0, 0.64, 0.61), sunset * (1.0 - night) * 0.65);\n        cloud = mix(cloud, skyZenith * 1.65 + vec3(0.07, 0.08, 0.11), night * 0.93);\n        color = mix(color, cloud, cloudMask * mix(0.91, 0.72, night));\n    }\n\n    finalColor = vec4(clamp(color, 0.0, 1.0), 1.0);\n}";
}
